import{_ as t,c as o,o as s,ag as n}from"./chunks/framework.DfL_BkQ-.js";const h=JSON.parse('{"title":"📚 Правила проекта","description":"","frontmatter":{},"headers":[],"relativePath":"rules/index.md","filePath":"rules/index.md"}'),a={name:"rules/index.md"};function p(e,r,g,l,i,c){return s(),o("div",null,[...r[0]||(r[0]=[n('<h1 id="📚-правила-проекта" tabindex="-1">📚 Правила проекта <a class="header-anchor" href="#📚-правила-проекта" aria-label="Permalink to &quot;📚 Правила проекта&quot;">​</a></h1><p>Дополнительную информацию уточняйте у персонала в дискорде.</p><div class="info custom-block"><p class="custom-block-title">Примечание</p><p>Основателем и единственным разработчиком проекта является <strong>tamraz</strong>.</p></div><div class="danger custom-block"><p class="custom-block-title">Внимание</p><p>Создавая аккаунт на ресурсах <strong>Manima</strong>, вы автоматически и безоговорочно подтверждаете свою <strong>ознакомленность</strong> и свое полное согласие с настоящим сводом правил, обязуясь не нарушать их.</p></div><h2 id="▌-0-предисловие" tabindex="-1">▌ 0. Предисловие <a class="header-anchor" href="#▌-0-предисловие" aria-label="Permalink to &quot;▌ 0. Предисловие&quot;">​</a></h2><p><strong>0.1.</strong> Взлом аккаунта или его передача не является оправданием в случае, когда вас обвиняют в нарушении правил.</p><p><strong>0.2.</strong> Обжалование любого наказания возможно в течение <strong>72 часов</strong> с момента его получения.</p><p><strong>0.3.</strong> Администрация оставляет за собой право определения любых мер наказаний и их сроков на свое усмотрение, без объяснения причин и предъявления доказательств.</p><p><strong>0.4.</strong> Администрация оставляет за собой право не возвращать игровые вещи, утраченные в результате багов, ошибок, откатов и прочих непредвиденных случаев. Но это не значит, что таких случаев не бывает. Зачастую игровые ценности возвращаются.</p><h2 id="▌-1-основные-принципы" tabindex="-1">▌ 1. Основные принципы <a class="header-anchor" href="#▌-1-основные-принципы" aria-label="Permalink to &quot;▌ 1. Основные принципы&quot;">​</a></h2><p><strong>1.1.</strong> <strong>Manima</strong> — это около ванильный сервер.</p><p><strong>1.2.</strong> На сервере <strong>Manima</strong> изменены и добавлены игровые механики, среди которых есть серьезно влияющие на игровой процесс.</p><p><strong>1.3.</strong> <strong>Manima</strong> — это PvP/PvE сервер, но, вопреки всему, это не значит, что здесь вы сможете потешить своё эго &quot;пвпшера&quot;. Если игрок не желает участвовать в PvP с вами, то в противном случае, такие убийства будут пресекаться. Однако, на сервере не запрещено PvP.</p><p><strong>1.4.</strong> На сервере <strong>Manima</strong> запрещено ругаться в глобальном чате, мешать другим игрокам, делать провокационные или оскорбительные заявления, троллить игроков, вести себя вызывающе или «токсично».</p><p><strong>1.5.</strong> <strong>Manima</strong> — это частный проект без каких-либо обязательств перед вами. Несмотря на это, разработчик всегда проводит работу по улучшению проекта.</p><p>Вы можете столкнуться с раздражающими проблемами или несовпадением ваших взглядов на игру со взглядами администратора.</p><blockquote><p><strong>Среди прочего это значит, что иногда для вас, как для игрока, единственный способ разрешить противоречия — это перестать играть на Manima и найти другой проект для игры.</strong></p></blockquote><h2 id="▌-2-правила-чата-игры" tabindex="-1">▌ 2. Правила чата игры <a class="header-anchor" href="#▌-2-правила-чата-игры" aria-label="Permalink to &quot;▌ 2. Правила чата игры&quot;">​</a></h2><p><strong>2.1.</strong> Запрещено нарушение правил сервера.</p><p><strong>2.2.</strong> Запрещено нарушение правил платформы <a href="https://www.twitch.tv/" target="_blank" rel="noreferrer">Twitch.tv</a>.</p><p><strong>2.3.</strong> Запрещено оскорбление игроков и групп лиц.</p><p><strong>2.4.</strong> Запрещено токсичное поведение.</p><p><strong>2.5.</strong> Запрещён спам, флуд, а также реклама сторонних ресурсов, не связанных с проектом.</p><p><strong>2.6.</strong> Запрещено использование слов из <a href="#список-запрещенных-слов">списка запрещенных слов</a>.</p><p><strong>2.7. Перечисленные выше действия применимы ко всем способам передачи информации как в игре, так и за ее пределами на наших порталах:</strong></p><ul><li>В игре: чат, таблички, книги, искусственные объекты.</li><li>За пределами игры: Discord сервер.</li></ul><h2 id="▌-3-игровои-клиент-и-его-модификации" tabindex="-1">▌ 3. Игровой клиент и его модификации <a class="header-anchor" href="#▌-3-игровои-клиент-и-его-модификации" aria-label="Permalink to &quot;▌ 3. Игровой клиент и его модификации&quot;">​</a></h2><p><strong>Следующие действия запрещены:</strong></p><p><strong>3.1.</strong> Использование модификаций и/или стороннего ПО, позволяющих получить преимущество в игровом процессе относительно стандартного немодифицированного игрового клиента — любые чит-клиенты, способы автоматизации, моды, ресурс-паки, текстур-паки и т.д.</p><p><strong>3.2.</strong> Использование багов игры для выполнения действий, недоступных для выполнения во время стандартного игрового процесса.</p><p><strong>Разрешено:</strong></p><p><strong>3.3.</strong> Использование миникарты, различных информационных модификаций (отображение уровня здоровья мобов, координат игрока, рецептов крафта) без отображение мобов и пещер.</p><ul><li>Пример разрешенной карты: <a href="https://www.curseforge.com/minecraft/mc-mods/xaeros-minimap-fair-play-edition" target="_blank" rel="noreferrer">Xaero&#39;s Minimap (Fair-Play Edition)</a>.</li></ul><h2 id="▌-4-игровая-активность" tabindex="-1">▌ 4. Игровая активность <a class="header-anchor" href="#▌-4-игровая-активность" aria-label="Permalink to &quot;▌ 4. Игровая активность&quot;">​</a></h2><p><strong>4.1.</strong> Запрещено создание искусственных объектов, которые:</p><ul><li><code>Не имеют практической ценности</code></li><li><code>Несут вульгарный или оскорбительный характер</code></li><li><code>Предназначены для создания препятствий игровому процессу других игроков</code></li></ul><p><strong>4.2.</strong> В случае, если механизм, в т.ч. использующий блоки-сущности, в процессе своей работы требует значительно больше вычислительных мощностей сервера, нежели остальные созданные механизмы в игровом мире, то он может быть удален из игрового мира, в том числе без предварительного уведомления его владельца.</p><p><strong>4.3.</strong> Запрещена любая из возможных авторыбалок.</p><p><strong>4.4.</strong> Запрещено использование системы игрового аукциона и/или магазинов для публичного размещения переименованных предметов, большого количества однотипных предметов, не несущих значимой ценности с точки зрения игровой экономики, использование этих систем не по прямому назначению, включая:</p><ul><li><code>размещение предметов с целью их хранения, а не продажи</code></li><li><code>размещение предметов с целью публикации какой-либо рекламной информации</code></li></ul><p><strong>4.5.</strong> Запрещены действия, направленные на получение игровой валюты от других игроков путем введения их в заблуждение касаемо последствий передачи игровой валюты.</p><p><strong>4.6.</strong> Не являются спорными ситуации, связанные с прямой передачей предметов одного игрока другому, осуществленной в том числе путем перемещения предметов в игровой мир. Для избежания спорных ситуаций игрокам необходимо использовать торговую площадку, доступную по команде <code>/ah</code>.</p><p><strong>4.7.</strong> Запрещено проведение массовых безвозмездных раздач предметов.</p><p><strong>4.8.</strong> В случае смерти игрового персонажа все предметы из его инвентаря считаются утраченными без возможности их восстановления, кроме случаев, когда смерть игрового персонажа спровоцирована нарушающими правила действиями других игроков.</p><p><strong>4.9.</strong> В случае подтвержденного факта утери предметов из-за технических проблем на стороне сервера предметы могут быть восстановлены при наличии возможности достоверно отследить и отменить последствия их использования другими игроками.</p><p><strong>4.10.</strong> Запрещено любое воспрепятствование работы системы AFK, в том числе автоматическая имитация активности игрового персонажа.</p><p><strong>4.11.</strong> Действия, последствия которых нарушают корректную работу сервера и его функционала, являются основанием для применения ограничений к игроку их спровоцировавшему.</p><p><strong>4.12.</strong> Запрещены мультиаккаунты при блокировке (обходы блокировок, новые аккаунты через впн и прочее).</p><p><strong>4.13.</strong> Запрещена накрутка любой статистики каким-либо способом.</p><p><strong>4.14.</strong> Запрещено нарушение работы развлекательных мероприятий на проекте, а также создание любых помех для организаторов.</p><p><strong>4.15.</strong> Запрещено использование непристойных скинов (содержащих наготу, нацистскую символику, символику организаций запрещенных на территории РФ, либо текст, нарушающий раздел правил чата).</p><h2 id="▌-5-система-приватов" tabindex="-1">▌ 5. Система приватов <a class="header-anchor" href="#▌-5-система-приватов" aria-label="Permalink to &quot;▌ 5. Система приватов&quot;">​</a></h2><p><strong>5.1.</strong> Запрещено создавать приваты без дальнейшего их использования, включая приват биомов, ресурсов, игровых структур и т.п. с целью воспрепятствования их использованию другими игроками.</p><p><strong>5.2.</strong> Игрокам, не являющимся участникам привата, запрещено осуществлять любое воздействие на зону привата или мобов в основной и прилегающих зонах привата.</p><p><strong>5.3.</strong> Запрещено создавать зоны привата с пересечением прилегающих зон привата других игроков без согласования с такими игроками.</p><p><strong>5.4.</strong> Любые деструктивные действия в основной и прилегающей зонах привата могут быть отменены по обращению игрока-владельца привата при наличии технической возможности.</p><ul><li><strong>5.4.1.</strong> Пункт 5.4. так же относится к тем случаям, когда как такового привата еще нет, но территория выбрана кем-либо для заселения (отстроен дом, либо стоят сундуки).</li></ul><p><strong>5.5.</strong> Систему привата запрещено использовать для присвоения любых игровых структур или редких биомов:</p><ul><li>Установка приватов на <strong>лесные особняки</strong> запрещена на сервере.</li><li>Установка приватов на <strong>грибные поля</strong> разрешена исключительно в пределах искусственных сооружений (не более 50% территории биома).</li></ul><h2 id="▌-6-сброс-неактивных-игровых-профилеи" tabindex="-1">▌ 6. Сброс неактивных игровых профилей <a class="header-anchor" href="#▌-6-сброс-неактивных-игровых-профилеи" aria-label="Permalink to &quot;▌ 6. Сброс неактивных игровых профилей&quot;">​</a></h2><p><strong>6.1.</strong> В случае, если игрок не входит в свой игровой профиль в течение <strong>90 дней</strong>, он считается неактивным.</p><p><strong>6.2.</strong> Следующие данные профилей неактивных игроков полностью удаляются без возможности восстановления:</p><ul><li>Баланс</li><li>Предметы в инвентаре и сундуке Края</li><li>Все характеристики персонажа (здоровье, опыт, эффекты и т.д.)</li><li>Все сохраненные позиции</li></ul><p><strong>6.3.</strong> Приваты, принадлежащие неактивному игроку, полностью очищаются и удаляются (если в них нет других активных участников).</p><p><strong>6.4.</strong> Для входа в неактивный профиль по-прежнему потребуется указать действующий пароль.</p><h2 id="▌-7-правила-модерации-проекта" tabindex="-1">▌ 7. Правила модерации проекта <a class="header-anchor" href="#▌-7-правила-модерации-проекта" aria-label="Permalink to &quot;▌ 7. Правила модерации проекта&quot;">​</a></h2><blockquote><p><strong>Модератор</strong> - игрок, наделенный особыми полномочиями для контроля порядка на игровых серверах.</p></blockquote><p><strong>7.1.</strong> Модератор должен уметь давать отчет своим действиям любому члену Администрации.</p><p><strong>7.2.</strong> Модератор не имеет права злоупотреблять своими полномочиями во вред игроку или в пользу себя/друзей.</p><p><strong>7.3.</strong> Модератор обязан быть грамотным, воспитанным, понимающим и толерантным.</p><p><strong>7.4.</strong> Модератор может быть отстранен от обязанностей в любой момент без предупреждений.</p><p><strong>7.5.</strong> Модератор имеет право продлевать/убавлять время наказания игрока, если к этому располагает ситуация.</p><p><strong>7.6.</strong> Модератор обязан предоставить Администрации доказательства вины игрока по первому требованию.</p><p><strong>7.7.</strong> Модератор не имеет права вносить раздор в персонал проекта.</p><p><strong>7.8.</strong> Модератор не имеет права снабжать игроков ресурсами, изъятыми у нарушителей.</p><p><strong>7.9.</strong> Модератор обязан контролировать игровой процесс и предотвращать инциденты.</p><p><strong>7.10.</strong> Модератору запрещено разглашать содержание конференций персонала.</p><p><strong>7.11.</strong> Модератору запрещено находиться долгое время на сервере в режиме AFK.</p><p><strong>7.12.</strong> Модератору запрещено оскорблять, унижать или провоцировать игроков.</p><div class="warning custom-block"><p class="custom-block-title">Последствия</p><p>За нарушение любого пункта правил модератор получит выговор или будет отстранен от должности.</p></div><h2 id="▌-8-пожертвования" tabindex="-1">▌ 8. Пожертвования <a class="header-anchor" href="#▌-8-пожертвования" aria-label="Permalink to &quot;▌ 8. Пожертвования&quot;">​</a></h2><p><strong>8.1.</strong> Сайт <a href="https://shop.manima.ru/" target="_blank" rel="noreferrer">shop.manima.ru</a> осуществляет приём пожертвований, поощряя Пользователей.</p><p><strong>8.2.</strong> Пользователь несет полную ответственность за свои пожертвования.</p><p><strong>8.3.</strong> Любые пожертвования могут быть проверены на предмет мошенничества.</p><p><strong>8.4.</strong> Проект не возвращает пожертвованные средства.</p><p><strong>8.5.</strong> Администрация сайта имеет право отказаться от пожертвований Пользователя.</p><h2 id="▌-9-дополнительная-информация" tabindex="-1">▌ 9. Дополнительная информация <a class="header-anchor" href="#▌-9-дополнительная-информация" aria-label="Permalink to &quot;▌ 9. Дополнительная информация&quot;">​</a></h2><blockquote><p>Текст, приведенный на этой странице, носит справочный характер и может быть изменен в любое время без уведомлений.</p></blockquote><p>Консультацию касаемо соответствия ваших действий принципам и правилам игрового процесса вы можете получить в <a href="https://discord.gg/mrwxrrKnwc" target="_blank" rel="noreferrer">Discord Manima</a>.</p><h2 id="▌-10-запрещенные-слова" tabindex="-1">▌ 10. Запрещённые слова <a class="header-anchor" href="#▌-10-запрещенные-слова" aria-label="Permalink to &quot;▌ 10. Запрещённые слова&quot;">​</a></h2><p>Запрещены все вариации нижеприведённых слов во всех смыслах, в том числе с использованием цензуры или иностранного языка:</p><div class="danger custom-block"><p class="custom-block-title">Открывайте на свой страх и риск</p><p>Нажмите ниже, чтобы увидеть список.</p></div><details class="details custom-block"><summary>🔞 Список запрещённых слов (Нажмите, чтобы открыть)</summary><ol><li>Ниггер</li><li>Пидор, пидорас, педик, гомосек</li><li>Даун, додик</li><li>Хач, чурка, пендос, жид и т.д.</li><li>Аутист, симп, инцел и т.д</li></ol><p><strong>ЗАПРЕЩЕННЫЕ МАТЕРИАЛЫ И ОРГАНИЗАЦИИ В РОССИИ</strong></p><p>Списки размещены на сайте <a href="https://minjust.gov.ru/ru/extremist-materials/" target="_blank" rel="noreferrer">Министерства юстиции РФ</a>, а также на сайте <a href="http://www.fsb.ru/fsb/npd/terror.htm" target="_blank" rel="noreferrer">ФСБ России</a>.</p></details>',93)])])}const u=t(a,[["render",p]]);export{h as __pageData,u as default};
